FILES_DIR = "/app/data/gaia_validation"

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--local_dir", default="/workspace/fanshengda/verl/input_data/xbench")
    parser.add_argument("--metadata_path",
                        default="/workspace/fanshengda/AgentCPM-MCP/evaluation/benchmarks/xbench/xbench.jsonl")
    args = parser.parse_args()

    data_source = "xbench"

    metadata = pd.read_json(args.metadata_path, lines=True)


    # add a row to each data item that represents a unique id

    def process_fn(example, idx):
        question = example['Question']

        system_message = deepcopy(gaia_system_prompt_content)
        if example['file_name']:
            user_prompt = MCP_USER_PROMPT_FOR_FILE.format(query=question, task_dir=FILES_DIR,
                                                          filename=example['file_name'])

        else:
            user_prompt = MCP_USER_PROMPT.format(query=question)
        solution = str(example['Final answer'])

        data = {
            "data_source": data_source,
            "prompt": [
                {
                    "role": "system",
                    "content": system_message,
                },
                {
                    "role": "user",
                    "content": user_prompt,
                }],
            "ability": "fact-reasoning",
            "reward_model": {
                "style": "rule",
                "ground_truth": solution
            },
            "extra_info": {
                'split': 'dev',
                'index': idx,
                'task_id': example['task_id'],
                'Level': example['Level'],
                'Annotator Metadata': example['Annotator Metadata'],
                'question': question,
                "need_tools_kwargs": True,
                # Ensure non-empty per-tool kwargs to avoid PyArrow struct<> write error
                # Ref: ArrowNotImplementedError: Cannot write struct type with no child field
                "tools_kwargs": {
                    item['function']['name']: {
                        "create_kwargs": {"ground_truth": solution}
                    }
                    for item in gaia_tools_content
                },
            }
        }
        return data


    train_dataset = pd.DataFrame([
        process_fn(row, idx) for idx, row in metadata.iterrows()
    ])

    local_dir = args.local_dir

    train_dataset.to_parquet(os.path.join(local_dir, "dev_docker232.parquet"))
    print('path:', os.path.join(local_dir, "dev_docker232.parquet"))